window.DATA = {"SB_N": 119611, "SB_EL": "", "SB_HK": ""};
window.META = {"name": "solar system", "caption": "About 120,000 real asteroids, <a href=\"https://en.wikipedia.org/wiki/Jupiter_trojan\" target=\"_blank\" rel=\"noopener\">Jupiter trojans</a>, <a href=\"https://en.wikipedia.org/wiki/Kuiper_belt\" target=\"_blank\" rel=\"noopener\">Kuiper belt</a> objects and comets from <a href=\"https://ssd.jpl.nasa.gov/tools/sbdb_query.html\" target=\"_blank\" rel=\"noopener\">JPL\u2019s Small-Body Database</a>, each moving on its own orbit. Distance is on a logarithmic scale so the planets and the <a href=\"https://en.wikipedia.org/wiki/Oort_cloud\" target=\"_blank\" rel=\"noopener\">Oort cloud</a> fit on one screen; the Oort cloud has never been observed and is a model.", "notice": ""};
// The Solar System out to the Oort cloud.
//
// Every asteroid, Trojan, Centaur, trans-Neptunian object and periodic comet is
// a real body from JPL's Small-Body Database, placed by its own osculating orbit
// and moved along it by solving Kepler's equation on the GPU. Planets use their
// J2000 mean elements. The Oort cloud has never been observed directly: it is a
// model (inner cloud 2,000-20,000 AU, outer to 100,000 AU, density ~ r^-3.5).
//
// Distance is drawn on a logarithmic scale, r' = 10 ln(1 + r / 0.4 AU): linear it
// would take 100,000 screens to hold the Oort cloud and the Earth together.
window.SCENE = {
  view: { radius: 68, el: 27, az: 60, roll: "diag", fov: 26, offset: [-0.06, 0.06], portraitYaw: 7 },
  exposure: 1.2, haze: 1.5, hazeFrac: 0.04, hazeSize: 1.0,
  timeScale: 1 / 6,          // years per second: the Earth goes round in six
  spin: 0.012,               // slow turntable, radians per second
  bg: 40000, bgExposure: 1.2,
  glsl: `
vec3 place(vec3 p, vec4 e, inout vec3 col, inout float flux) {
  float a = p.x, ecc = p.y, inc = p.z;
  if (a <= 0.0) return e.xyz;                          // the Sun: still points, their offsets in e
  float n = 6.2831853 / (a * sqrt(a));                 // radians per year
  float M = mod(e.z + n * uTime, 6.2831853);
  float E = ecc < 0.8 ? M : 3.14159265;
  for (int k = 0; k < 10; k++) E -= (E - ecc * sin(E) - M) / (1.0 - ecc * cos(E));
  float xv = a * (cos(E) - ecc), yv = a * sqrt(1.0 - ecc * ecc) * sin(E);
  float cw = cos(e.y), sw = sin(e.y), cO = cos(e.x), sO = sin(e.x), ci = cos(inc), si = sin(inc);
  float x1 = cw * xv - sw * yv, y1 = sw * xv + cw * yv;
  vec3 r = vec3(cO * x1 - sO * y1 * ci, sO * x1 + cO * y1 * ci, y1 * si);
  float d = length(r);
  return r / max(d, 1e-6) * 10.0 * log(1.0 + d / 0.4);
}`,
  build(ctx) {
    const { rnd, gauss, b64, DEG, lite } = ctx;
    const D = window.DATA;
    const out = [];
    const put = (a, e, i, O, w, M, c, f) => out.push(a, e, i, c[0], c[1], c[2], f, O, w, M, 0);

    // the Sun: a bright still core inside a soft glow
    for (let k = 0; k < 60; k++) out.push(0, 0, 0, 1.0, 0.95, 0.85, 4.0, gauss() * 0.06, gauss() * 0.06, gauss() * 0.06, 0);
    for (let k = 0; k < 400; k++) out.push(0, 0, 0, 1.0, 0.82, 0.55, 0.35, gauss() * 0.3, gauss() * 0.3, gauss() * 0.3, 0);

    // small bodies from JPL
    const EL = b64(D.SB_EL, Uint16Array), HK = b64(D.SB_HK, Uint8Array);
    const LA0 = Math.log(0.1), LA1 = Math.log(4e5);
    const COL = [
      [0.95, 0.84, 0.68],   // main belt
      [1.00, 0.72, 0.52],   // Mars-crossers
      [1.00, 0.52, 0.34],   // near-Earth
      [1.00, 0.80, 0.42],   // Jupiter Trojans
      [0.95, 0.84, 0.68],   // Hildas
      [0.58, 0.76, 1.00],   // trans-Neptunian
      [0.55, 0.95, 0.90],   // Centaurs
      [0.70, 1.00, 0.82],   // comets
    ];
    const skip = lite ? 2 : 1;
    for (let k = 0; k < D.SB_N; k++) {
      const cls = HK[k * 2 + 1];
      if (lite && cls === 0 && k % skip) continue;
      const q = (j, lo, hi) => lo + EL[k * 6 + j] / 65535 * (hi - lo);
      const a = Math.exp(q(0, LA0, LA1));
      const H = HK[k * 2] / 8;
      const kuiper = cls === 5 || cls === 6;
      const belt = cls === 0 || cls === 1 || cls === 4;   // main belt, Mars-crossers, Hildas
      // Jupiter's Trojans travel in two tight swarms, 60 degrees ahead of and behind the
      // planet; seen edge-on each one stacks up into a bright arc, so they stay faint
      const f = cls === 3 ? Math.min(0.5, 0.02 + 0.06 * Math.pow(10, -0.2 * (H - 11)))
              : kuiper ? Math.min(2.5, 0.18 + 0.45 * Math.pow(10, -0.2 * (H - 7)))
              : belt ? Math.min(1.0, 0.025 + 0.11 * Math.pow(10, -0.2 * (H - 11)))
              : Math.min(7, 0.35 + 1.6 * Math.pow(10, -0.2 * (H - 11)));
      put(a, q(1, 0, 1), q(2, 0, 180) * DEG, q(3, 0, 360) * DEG, q(4, 0, 360) * DEG, q(5, 0, 360) * DEG, COL[cls], f);
    }

    // planets (J2000 mean elements: a, e, i, node, longitude of perihelion, mean longitude), moved to 2026-09-26
    const PL = [
      [0.3871, 0.2056, 7.005, 48.331, 77.456, 252.251, [0.85, 0.8, 0.75], 5],
      [0.7233, 0.0068, 3.395, 76.680, 131.533, 181.980, [1.0, 0.95, 0.8], 9],
      [1.0000, 0.0167, 0.000, -11.26, 102.947, 100.464, [0.6, 0.8, 1.0], 9],
      [1.5237, 0.0934, 1.850, 49.558, 336.041, 355.453, [1.0, 0.6, 0.4], 7],
      [5.2026, 0.0485, 1.303, 100.464, 14.331, 34.351, [1.0, 0.88, 0.7], 14],
      [9.5549, 0.0555, 2.489, 113.665, 93.057, 50.077, [1.0, 0.9, 0.65], 12],
      [19.218, 0.0464, 0.773, 74.006, 173.005, 314.055, [0.7, 0.95, 1.0], 9],
      [30.110, 0.0086, 1.770, 131.784, 48.124, 304.349, [0.5, 0.65, 1.0], 9],
    ];
    const DT = (2461309.5 - 2451545.0) / 365.25;
    for (const [a, e, i, O, pi, L, c, f] of PL) {
      const n = 360 / Math.pow(a, 1.5);
      const M = ((L - pi + n * DT) % 360) * DEG;
      for (let k = 0; k < 12; k++) put(a, e, i * DEG, O * DEG, (pi - O) * DEG, M, c, f);   // stacked for a brighter point
      // the orbit as a faint dotted ring, moving with the planet
      const dots = 500;
      for (let k = 0; k < dots; k++) put(a, e, i * DEG, O * DEG, (pi - O) * DEG, M + (k + 1) / (dots + 1) * 2 * Math.PI, [0.7, 0.75, 0.9], 0.18);
    }

    // Oort cloud (model): inner cloud flattened toward the ecliptic, outer isotropic
    const NO = lite ? 14000 : 30000;
    const lo = Math.pow(2000, -2.5), hi = Math.pow(100000, -2.5);
    for (let k = 0; k < NO; k++) {
      const a = Math.pow(lo - rnd() * (lo - hi), -1 / 2.5);   // n(a) ~ a^-3.5 per volume -> a^-1.5 per shell... close enough
      const ecc = Math.sqrt(rnd()) * 0.95;
      const inner = a < 20000;
      const inc = inner ? Math.abs(gauss()) * 35 * DEG : Math.acos(rnd() * 2 - 1);
      put(a, ecc, inc, rnd() * 2 * Math.PI, rnd() * 2 * Math.PI, rnd() * 2 * Math.PI, [0.72, 0.82, 1.0], 0.22 + 0.35 * Math.pow(rnd(), 8));
    }
    return { data: new Float32Array(out) };
  },
};
